custom_css:
/* ===== src/tokens.css ===== */
/*
 * 红莓序章 by @jiuyi0204
 * 未经作者明确许可，禁止二次修改、二次上传、转载、重新打包或冒名发布。
 * 第三方字体与素材继续遵守各自原许可证。
 */
@font-face {
  font-family: "Huiwen-mincho";
  src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/huiwenmincho-improved/HuiwenMincho-Improved-Regular.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

@font-face {
  font-family: "Cormorant SC";
  src: url("https://raw.githubusercontent.com/jiuyi777/sillytavern-theme-assets/2b1972108f9dc4082438d5f0fbeebe81d1d4b1ef/font-library/v2/fonts/cormorant-sc/CormorantSC-Regular.woff2") format("woff2");
  font-style: normal;
  font-weight: 400;
  font-display: swap;
}

:root {
  --rb-chocolate: #2b1718;
  --rb-chocolate-2: #3b2422;
  --rb-berry: #8f2f35;
  --rb-strawberry: #bd4b4d;
  --rb-paper: #f7f1e6;
  --rb-paper-2: #efe5d5;
  --rb-ink: #3d2b2a;
  --rb-muted: #7e6861;
  --rb-sage: #6f7f57;
  --rb-sage-dark: #4f6040;
  --rb-gold: #c9aa73;
  --rb-paper-raised: #fffaf1;
  --rb-soft-rose: #ead7ce;
  --rb-disabled-ink: #8b625b;
  --rb-disabled-bg: #eaded0;
  --rb-info: #71835c;
  --rb-line: rgba(143, 47, 53, .28);
  --rb-shadow: 0 .65rem 1.8rem rgba(43, 23, 24, .16);
  --rb-hairline: 1px solid var(--rb-line);
  --rb-radius-sm: .35rem;
  --rb-radius: .75rem;
  --rb-radius-lg: 1.25rem;
  --rb-font-body: "Huiwen-mincho", "Source Han Serif SC", "Noto Serif SC", serif;
  --rb-font-display: "Cormorant SC", "Huiwen-mincho", serif;
}

body {
  --SmartThemeBodyColor: var(--rb-ink);
  --SmartThemeEmColor: var(--rb-strawberry);
  --SmartThemeQuoteColor: var(--rb-berry);
  --SmartThemeBlurTintColor: rgba(247, 241, 230, .97);
  --SmartThemeChatTintColor: rgba(247, 241, 230, .98);
  --SmartThemeBorderColor: rgba(143, 47, 53, .32);
  --SmartThemeShadowColor: rgba(43, 23, 24, .14);
  --SmartThemeBlurStrength: 0;
  --shadowWidth: 0;
  color: var(--rb-ink);
  background-color: var(--rb-chocolate);
  font-family: var(--rb-font-body);
  color-scheme: light;
}

#bg1,
#bg_custom {
  background-color: var(--rb-chocolate);
}

::selection {
  color: var(--rb-paper);
  background: var(--rb-berry);
}


/* ===== src/kernel/scrollbars.css ===== */
::-webkit-scrollbar {
  display: none !important;
}

* {
  scrollbar-width: none !important;
  -ms-overflow-style: none !important;
}


/* ===== src/kernel/compatibility.css ===== */
/* 功能与状态保护：不承载固定构图。 */
#chat .mes,
#chat .mes_block,
#chat .mes_text,
#send_form,
#send_textarea {
  min-width: 0;
}

#chat .mes_buttons,
#chat .mes_edit_buttons,
#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter,
#send_form .interactable,
#send_form .mes_stop,
#top-settings-holder .drawer-icon {
  position: relative;
  z-index: 2;
}

#chat .mes_buttons:focus-within,
#send_form .interactable:focus-visible,
#send_form .mes_stop:focus-visible,
#top-settings-holder .drawer-icon:focus-visible,
.menu_button:focus-visible {
  outline: 2px solid var(--rb-gold);
  outline-offset: 3px;
}

#chat .mes.selected {
  box-shadow: inset .25rem 0 0 var(--rb-strawberry);
}

@media (prefers-reduced-motion: reduce) {
  #chat .mes,
  #top-settings-holder .drawer-icon,
  #send_form .interactable,
  .menu_button {
    transition-duration: .01ms;
    animation-duration: .01ms;
    animation-iteration-count: 1;
  }
}


/* ===== src/chat-layout.css ===== */
#chat {
  color: var(--rb-ink);
  background: var(--rb-paper);
  border: 0;
  box-shadow: var(--rb-shadow);
  text-shadow: none;
  scrollbar-color: var(--rb-sage) var(--rb-paper-2);
}

#chat .mes {
  display: grid;
  position: relative;
  align-items: start;
  width: 100%;
  margin: 0;
  padding: clamp(1rem, 2.2vw, 2rem);
  color: var(--rb-ink);
  background: var(--rb-paper);
  border: 0;
  border-bottom: var(--rb-hairline);
  text-shadow: none;
}

#chat .mes[is_user="true"] {
  --avatar-size: 40%;
  --avatar-gap: clamp(.9rem, 2vw, 1.6rem);
  --avatar-slot: calc(var(--avatar-size) + var(--avatar-gap));
  grid-template-columns: minmax(0, var(--avatar-size)) minmax(0, 1fr);
  gap: var(--avatar-gap);
  color: var(--rb-paper);
  background: var(--rb-chocolate);
  border-bottom-color: rgba(201, 170, 115, .38);
}

#chat .mes[is_user="true"]::before {
  content: "F  |  RED BERRY PROLOGUE";
  grid-column: 1 / -1;
  grid-row: 1;
  color: rgba(247, 241, 230, .72);
  font: 400 .72em/1 var(--rb-font-display);
  letter-spacing: .2em;
  pointer-events: none;
}

#chat .mes[is_user="true"] .mesAvatarWrapper {
  grid-column: 1;
  grid-row: 2;
  display: grid;
  grid-template-columns: repeat(3, auto) 1fr;
  gap: .35rem .7rem;
  width: 100%;
  color: rgba(247, 241, 230, .62);
  align-content: start;
}

#chat .mes[is_user="true"] .avatar {
  grid-column: 1 / -1;
  position: relative;
  width: 100%;
  height: auto;
  aspect-ratio: 16 / 6;
  overflow: hidden;
  flex: none;
  border: 1px solid rgba(201, 170, 115, .55);
  border-radius: 0;
  background: var(--rb-chocolate-2);
  box-shadow: 0 .5rem 1.4rem rgba(43, 23, 24, .28);
}

#chat .mes[is_user="true"] .avatar img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 38%;
  border: 0;
  border-radius: 0;
  box-shadow: none;
}

#chat .mes[is_user="true"] .mes_block {
  grid-column: 2;
  grid-row: 2;
  align-self: center;
  width: 100%;
  padding: 0;
  overflow: visible;
}

#chat .mes[is_user="true"] .ch_name {
  padding-bottom: .75rem;
  color: var(--rb-paper);
  border-bottom: 1px solid rgba(201, 170, 115, .32);
}

#chat .mes[is_user="true"] .name_text {
  color: var(--rb-paper);
  font-family: var(--rb-font-display);
  font-size: 1.05em;
  letter-spacing: .14em;
  text-transform: uppercase;
}

#chat .mes[is_user="true"] .timestamp,
#chat .mes[is_user="true"] .mes_buttons,
#chat .mes[is_user="true"] .mes_edit_buttons {
  color: rgba(247, 241, 230, .66);
}

#chat .mes[is_user="false"][is_system="false"] {
  --avatar-size: 2rem;
  --avatar-gap: .75rem;
  --avatar-slot: calc(var(--avatar-size) + var(--avatar-gap));
  grid-template-columns: var(--avatar-size) minmax(0, 1fr);
  gap: var(--avatar-gap);
  padding-top: clamp(1.4rem, 2.8vw, 2.4rem);
  padding-bottom: clamp(1.8rem, 3.5vw, 3.2rem);
}

#chat .mes[is_user="false"][is_system="false"] .mesAvatarWrapper {
  grid-column: 1;
  grid-row: 1;
  display: flex;
  flex-direction: column;
  width: var(--avatar-size);
  gap: .25rem;
  color: var(--rb-muted);
  align-items: center;
}

#chat .mes[is_user="false"][is_system="false"] .avatar,
#chat .mes[is_user="false"][is_system="false"] .avatar img {
  width: var(--avatar-size);
  height: var(--avatar-size);
  flex: none;
  border-radius: 50%;
}

#chat .mes[is_user="false"][is_system="false"] .avatar img {
  border: 1px solid var(--rb-strawberry);
  box-shadow: 0 0 0 .2rem rgba(189, 75, 77, .09);
}

#chat .mes[is_user="false"][is_system="false"] .mes_block {
  grid-column: 1 / -1;
  grid-row: 1;
  position: relative;
  width: 100%;
  max-width: 100%;
  padding: 0;
  overflow: visible;
}

#chat .mes[is_user="false"][is_system="false"] .mes_block::after {
  content: "NOTES\A Fragaria vesca";
  display: block;
  width: 100%;
  margin-top: 1rem;
  padding-top: .45rem;
  color: var(--rb-strawberry);
  border-top: 1px solid var(--rb-strawberry);
  white-space: pre-line;
  text-align: right;
  font: 400 .72em/1.6 var(--rb-font-display);
  letter-spacing: .08em;
  pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"] .ch_name {
  min-height: var(--avatar-size);
  margin-inline-start: var(--avatar-slot);
  padding-bottom: .65rem;
  border-bottom: 1px dashed rgba(143, 47, 53, .28);
}

#chat .mes[is_user="false"][is_system="false"] .name_text {
  color: var(--rb-strawberry);
  font-family: var(--rb-font-display);
  font-size: 1.1em;
  letter-spacing: .18em;
  text-transform: uppercase;
}

#chat .timestamp {
  margin-inline-start: .9em;
  color: var(--rb-muted);
  font-size: .78em;
  letter-spacing: .04em;
}

#chat .mes_buttons,
#chat .mes_edit_buttons {
  color: var(--rb-berry);
  filter: none;
  text-shadow: none;
}

#chat .mes_button,
#chat .mes_edit_buttons .menu_button {
  color: var(--rb-berry);
  border-radius: 0;
  background: transparent;
  box-shadow: none;
  filter: none;
  opacity: .88;
  text-shadow: none;
}

#chat .mes_button:hover,
#chat .mes_button:focus-visible,
#chat .mes_edit_buttons .menu_button:hover,
#chat .mes_edit_buttons .menu_button:focus-visible {
  color: var(--rb-strawberry);
  filter: none;
  opacity: 1;
  text-shadow: none;
}

#chat .mes[is_system="true"] {
  grid-template-columns: 2rem minmax(0, 1fr);
  gap: .7rem;
  margin: .65rem 0;
  padding: .8rem 1rem;
  color: var(--rb-sage-dark);
  background: rgba(111, 127, 87, .09);
  border-block: 1px solid rgba(111, 127, 87, .25);
}

#chat .mes[is_system="true"] .avatar {
  filter: none;
  opacity: .9;
}

#chat .mes.smallSysMes {
  border-radius: 0;
}

#chat .mes_reasoning_details {
  width: 100%;
  max-width: 72ch;
  margin: .8rem auto 1rem;
  color: var(--rb-ink);
  background: var(--rb-paper-2);
  border: 1px solid rgba(143, 47, 53, .28);
  border-radius: var(--rb-radius-sm);
  box-shadow: none;
  filter: none;
  text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning_header,
#chat .mes_reasoning_details .mes_reasoning_summary {
  color: var(--rb-berry);
  background: var(--rb-soft-rose);
  border: 1px solid rgba(143, 47, 53, .26);
  box-shadow: none;
  filter: none;
  opacity: 1;
  text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning_header:is(:hover, :focus-visible) {
  color: var(--rb-sage-dark);
  background: rgba(201, 170, 115, .18);
  border-color: var(--rb-gold);
}

#chat .mes_reasoning_details .mes_reasoning {
  color: var(--rb-ink);
  background: var(--rb-paper-raised);
  border-left-color: var(--rb-berry);
  filter: none;
  text-shadow: none;
}

#chat .mes_reasoning_details .mes_reasoning_arrow {
  color: var(--rb-berry);
  filter: none;
  text-shadow: none;
}

#chat .swipe_left,
#chat .swipe_right,
#chat .swipes-counter {
  color: var(--rb-berry);
}


/* ===== src/full-text.css ===== */
#chat .mes_text {
  max-width: 72ch;
  padding: .8rem 0 .2rem;
  color: inherit;
  font-family: var(--rb-font-body);
  font-size: 1em;
  font-weight: 400;
  line-height: 1.9;
  overflow-wrap: anywhere;
}

#chat .mes[is_user="true"] .mes_text {
  max-width: 46ch;
  padding-top: 1rem;
  color: var(--rb-paper);
  font-size: 1.06em;
  line-height: 1.85;
  letter-spacing: .04em;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text {
  width: 100%;
  margin-inline: auto;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text::after {
  content: "✦  ❦  ✦";
  display: block;
  margin: 1.35em auto .15em;
  color: var(--rb-strawberry);
  text-align: center;
  font: 400 .72em/1 var(--rb-font-display);
  letter-spacing: .36em;
  opacity: .62;
  pointer-events: none;
}

#chat .mes[is_user="false"][is_system="false"] .mes_text > p:first-child::first-letter {
  float: left;
  margin: .07em .16em 0 0;
  color: var(--rb-strawberry);
  font-family: var(--rb-font-display);
  font-size: 2.9em;
  line-height: .82;
}

#chat .mes_text p {
  margin: 0 0 1em;
}

#chat .mes_text h1,
#chat .mes_text h2,
#chat .mes_text h3,
#chat .mes_text h4 {
  margin: 1.25em 0 .65em;
  color: var(--rb-berry);
  font-family: var(--rb-font-display);
  font-weight: 400;
  letter-spacing: .08em;
}

#chat .mes_text blockquote {
  margin: 1.2em 0;
  padding: .25em 1.15em;
  color: var(--rb-muted);
  background: rgba(189, 75, 77, .045);
  border-left: .18em solid var(--rb-strawberry);
  font-style: normal;
}

#chat .mes[is_user="true"] .mes_text blockquote {
  color: rgba(247, 241, 230, .78);
  background: rgba(247, 241, 230, .06);
  border-left-color: var(--rb-gold);
}

#chat .mes_text a {
  color: var(--rb-berry);
  text-decoration-color: rgba(143, 47, 53, .38);
  text-underline-offset: .16em;
}

#chat .mes_text em {
  color: var(--rb-strawberry);
  font-style: normal;
  letter-spacing: .04em;
}

#chat .mes_text strong {
  color: var(--rb-berry);
  font-weight: 400;
  letter-spacing: .06em;
}

#chat .mes_text hr {
  width: 0;
  height: 0;
  margin: 1.15em auto;
  opacity: 0;
  border: 0;
  background: none;
}

#chat .mes_text pre,
#chat .mes_text code {
  font-family: "Courier Prime", ui-monospace, monospace;
}

#chat .mes_text pre {
  max-width: 100%;
  overflow-x: auto;
  padding: 1em;
  color: var(--rb-paper);
  background: var(--rb-chocolate-2);
  border-left: .2rem solid var(--rb-sage);
  border-radius: var(--rb-radius-sm);
}

#chat .mes_text :not(pre) > code {
  padding: .12em .32em;
  color: var(--rb-berry);
  background: rgba(143, 47, 53, .08);
  border-radius: .18em;
}

#chat .mes_text table {
  display: block;
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
  border-collapse: collapse;
}

#chat .mes_text th,
#chat .mes_text td {
  padding: .55em .75em;
  border: var(--rb-hairline);
}

#chat .mes_text th {
  color: var(--rb-paper);
  background: var(--rb-sage-dark);
  font-weight: 400;
}

#chat .mes_text img,
#chat .mes_media_wrapper img,
#chat .mes_video_container,
#chat .mes_file_wrapper {
  max-width: 100%;
}


/* ===== src/windows/welcome.css ===== */
.welcomePanel {
  color: var(--rb-ink);
  background: var(--rb-paper);
  text-shadow: none;
}

.welcomePanel :is(.welcomeHeaderVersionDisplay, .recentChatsTitle, .chatName) {
  color: var(--rb-chocolate-2);
}

.welcomePanel .recentChatList .recentChat {
  color: var(--rb-ink);
  background: var(--rb-paper-raised);
  border-color: rgba(143, 47, 53, .32);
  box-shadow: 0 .16rem .45rem rgba(43, 23, 24, .06);
}

.welcomePanel .recentChatList .recentChat:hover {
  background: var(--rb-soft-rose);
}

.welcomePanel .recentChatList .recentChat .chatNameContainer {
  font-size: calc(var(--mainFontSize) * 1.04);
}

.welcomePanel .recentChatList .recentChat .chatMessageContainer {
  color: var(--rb-ink);
  font-size: calc(var(--mainFontSize) * .94);
}

.welcomePanel .recentChatList .recentChat :is(.chatStats, .chatDate, .counterBlock) {
  color: var(--rb-muted);
  opacity: 1;
}

.welcomePanel .recentChatList .recentChat .chatActions button {
  color: var(--rb-berry);
  background: var(--rb-paper-2);
  border-color: rgba(143, 47, 53, .28);
  filter: none;
  opacity: 1;
  text-shadow: none;
}

.welcomePanel .recentChatList .recentChat .chatActions button:is(:hover, :focus-visible) {
  color: var(--rb-paper-raised);
  background: var(--rb-berry);
  border-color: var(--rb-gold);
}


/* ===== src/windows/topbar.css ===== */
#top-bar {
  color: var(--rb-paper);
  background: var(--rb-chocolate);
  border-bottom: 1px solid rgba(201, 170, 115, .38);
  box-shadow: none;
  backdrop-filter: none;
  text-shadow: none;
}

#top-settings-holder {
  color: var(--rb-gold);
  background: transparent;
  text-shadow: none;
}

#top-settings-holder .drawer-toggle,
#top-settings-holder .drawer-header,
#top-settings-holder .drawer-icon {
  background: transparent;
  border: 0;
  box-shadow: none;
}

#top-settings-holder .drawer-toggle {
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

#top-settings-holder:has(> .drawer > .drawer-content.openDrawer) {
  z-index: 4005;
  isolation: isolate;
}

#top-settings-holder > .drawer > .drawer-content.openDrawer {
  background: rgba(247, 241, 230, .995);
  box-shadow: none;
  filter: none;
  pointer-events: auto;
}

#top-settings-holder .drawer-icon {
  color: var(--rb-gold);
  filter: none;
  opacity: .82;
  text-shadow: none;
  transition: color .18s ease, opacity .18s ease, text-shadow .18s ease;
}

#top-settings-holder .drawer-icon:hover,
#top-settings-holder .drawer-icon:focus-visible,
#top-settings-holder .drawer-icon.openIcon {
  color: var(--rb-paper);
  opacity: 1;
  text-shadow: none;
}

#top-settings-holder .drawer-icon:active {
  color: var(--rb-strawberry);
  opacity: 1;
  text-shadow: none;
}

#top-settings-holder .drawer-icon:is(.disabled, [aria-disabled="true"]) {
  color: var(--rb-disabled-ink);
  filter: none;
  opacity: .58;
  text-shadow: none;
}

#ai-config-button .drawer-icon,
#advanced-formatting-button .drawer-icon,
#user-settings-button .drawer-icon {
  color: #d6c58e;
}

#advanced-formatting-button .drawer-icon.openIcon:not(.disabled):not([aria-disabled="true"]) {
  color: var(--rb-berry);
  background: var(--rb-soft-rose);
  box-shadow: inset 0 -.18rem 0 var(--rb-strawberry);
  filter: none;
  opacity: 1;
  text-shadow: none;
}

#sys-settings-button .drawer-icon,
#WI-SP-button .drawer-icon,
#persona-management-button .drawer-icon {
  color: #d08a72;
}

#backgrounds-button .drawer-icon,
#extensions-settings-button .drawer-icon,
#rightNavHolder .drawer-icon {
  color: #a5b27f;
}


/* ===== src/windows/input.css ===== */
#send_form {
  color: var(--rb-paper);
  background: var(--rb-sage-dark);
  border: 0;
  border-top: 1px solid rgba(201, 170, 115, .42);
  border-radius: 0 0 var(--rb-radius-lg) var(--rb-radius-lg);
  box-shadow: none;
  backdrop-filter: none;
}

#send_form #nonQRFormItems {
  gap: .35rem;
  padding: .38rem;
}

#send_textarea {
  min-height: 2.7rem;
  padding: .72rem 1rem;
  color: var(--rb-ink);
  background: var(--rb-paper);
  border: 1px solid rgba(201, 170, 115, .5);
  border-radius: var(--rb-radius);
  box-shadow: none;
  font-family: var(--rb-font-body);
  font-size: 1em;
  line-height: 1.55;
  caret-color: var(--rb-strawberry);
}

#send_textarea::placeholder {
  color: rgba(61, 43, 42, .48);
}

#send_textarea:focus-visible {
  outline: 2px solid var(--rb-gold);
  outline-offset: 2px;
}

#send_form:has(#send_textarea:focus-visible) {
  border-top-color: var(--rb-gold);
}

#options_button,
#extensionsMenuButton,
#send_but,
#mes_continue,
#mes_impersonate,
#send_form .mes_stop,
#rightSendForm .stscript_btn {
  color: var(--rb-berry);
  background: transparent;
  border: 0;
  border-radius: 0;
  box-shadow: none;
  filter: none;
  opacity: 1;
  text-shadow: none;
}

#options_button:is(:hover, :focus-visible),
#extensionsMenuButton:is(:hover, :focus-visible),
#send_but:is(:hover, :focus-visible),
#mes_continue:is(:hover, :focus-visible),
#mes_impersonate:is(:hover, :focus-visible),
#rightSendForm .stscript_btn:is(:hover, :focus-visible) {
  color: var(--rb-gold);
}

#options_button:active,
#extensionsMenuButton:active,
#send_but:active,
#mes_continue:active,
#mes_impersonate:active,
