/* ===== src/windows/mobile.css ===== */
@media (max-width: 700px) {
  #chat .mes {
    padding: 1rem .85rem;
  }

  #chat .mes[is_user="true"] {
    --avatar-size: 100%;
    --avatar-gap: .8rem;
    --avatar-slot: 100%;
    grid-template-columns: minmax(0, 1fr);
    gap: var(--avatar-gap);
    min-height: 0;
  }

  #chat .mes[is_user="true"] .mesAvatarWrapper,
  #chat .mes[is_user="true"] .mes_block {
    grid-column: 1;
    grid-row: auto;
  }

  #chat .mes[is_user="true"] .mesAvatarWrapper {
    margin-top: 0;
  }

  #chat .mes[is_user="true"] .avatar {
    height: auto;
    aspect-ratio: 16 / 7;
  }

  #chat .mes[is_user="true"] .mes_block {
    padding-top: .2rem;
  }

  #chat .mes[is_user="false"][is_system="false"] {
    --avatar-size: 1.75rem;
    --avatar-gap: .55rem;
    --avatar-slot: calc(var(--avatar-size) + var(--avatar-gap));
    grid-template-columns: var(--avatar-size) minmax(0, 1fr);
  }

  #chat .mes[is_user="false"][is_system="false"] .mes_block {
    padding-right: 0;
  }

  #chat .mes[is_user="false"][is_system="false"] .mes_block::after {
    margin-top: 1rem;
    padding-top: .4rem;
  }

  #chat .mes_text,
  #chat .mes[is_user="true"] .mes_text {
    max-width: 100%;
  }

  #send_form {
    padding-bottom: env(safe-area-inset-bottom, 0);
    border-radius: 0;
  }

  #send_form.compact {
    --bottomFormBlockPadding: .16rem;
    --bottomFormIconSize: 1.55rem;
  }

  #send_form.compact #nonQRFormItems {
    align-items: center;
    flex-wrap: nowrap;
    gap: .15rem;
    padding: .2rem .25rem;
  }

  #send_form.compact :is(#leftSendForm, #rightSendForm) {
    flex: 0 0 auto;
    flex-wrap: nowrap;
    width: auto;
  }

  #send_form.compact #send_textarea {
    flex: 1 1 auto;
    min-width: 0;
    width: 0;
    min-height: calc(var(--mainFontSize) * 2.2);
    height: auto;
    max-height: min(calc(var(--mainFontSize) * 8), 32dvh);
    padding: calc(var(--mainFontSize) * .32) calc(var(--mainFontSize) * .6);
    box-sizing: border-box;
    font-size: calc(var(--mainFontSize) * .88);
    line-height: 1.35;
  }

  #send_form.compact #send_textarea::placeholder {
    font-size: 1em;
  }

  #send_form.compact :is(
    #options_button,
    #extensionsMenuButton,
    #send_but,
    #mes_continue,
    #mes_impersonate,
    .mes_stop,
    .stscript_btn
  ) {
    width: var(--bottomFormBlockSize);
    min-width: var(--bottomFormBlockSize);
    height: var(--bottomFormBlockSize);
    margin-inline: 0;
    font-size: var(--bottomFormIconSize);
  }

  #left-nav-panel,
  #rm_api_block,
  #AdvancedFormatting,
  #WorldInfo,
  #user-settings-block,
  #Backgrounds,
  #rm_extensions_block,
  #PersonaManagement,
  #right-nav-panel,
  #floatingPrompt,
  #cfgConfig,
  #logprobsViewer,
  #completion_prompt_manager_popup,
  #character_popup,
  #select_chat_popup,
  #world_popup,
  #dialogue_popup {
    border-radius: 0;
    box-shadow: none;
  }
}


/* ===== src/fallback.css ===== */
@supports not (display: grid) {
  #chat .mes {
    display: flex;
  }

  #chat .mes[is_user="true"] {
    flex-direction: column;
  }

  #chat .mes[is_user="true"] .mesAvatarWrapper,
  #chat .mes[is_user="true"] .mes_block {
    width: 100%;
  }
}

@media (forced-colors: active) {
  #chat .mes,
  #send_form,
  .drawer-content,
  .popup-content {
    border: 1px solid CanvasText;
  }
}
